"""Build the 60 executions: isolated material copies, prompts (generated by the shipped code), random order."""

from __future__ import annotations

import json
import random
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).parent
SKILL = Path(r"D:\cc-wt\contracts\skills\core\contract")
sys.path.insert(0, str(SKILL))
import contracts_lib as lib  # noqa: E402

# live-install index (as on the owner's machine: personal skills and agents resolve), rebuilt before use
index = lib.load_index(HERE / "live_index.json")
assert index is not None and len(index["cards"]) >= 41

TASKS = {  # task -> (card for F, wrong card for W)
    "t01": ("statistical-audit", "experiment-protocol"),
    "t02": ("dataset-leakage-audit", "statistical-audit"),
    "t03": ("performance-audit", "algorithmic-complexity"),
    "t04": ("hard-bug-localization", "concurrency-audit"),
    "t05": ("concurrency-audit", "hard-bug-localization"),
    "t06": ("reproducible-experiment", "reproducible-build"),
    "t07": ("causal-claim-audit", "statistical-audit"),
    "t08": ("api-compat-contract", "dependency-modernization"),
    "t09": ("test-coverage-synthesis", "invariants-verification"),
    "t10": ("paper-falsification-audit", "systematic-review"),
}
# canonical prompts that make the shipped router select each card (same ones the test-suite pins)
CANON = {
    "statistical-audit": "проверь p-value и множественные сравнения в этой работе",
    "dataset-leakage-audit": "проверь, есть ли утечка данных между train и test, кросс-валидация по датасету",
    "performance-audit": "хочу ускорить хук, p95 латентность, найди узкое место",
    "hard-bug-localization": "найди первопричину нерегулярной ошибки: flaky дефект, root cause",
    "concurrency-audit": "проверь код на race condition и deadlock, атомарность и двойное выполнение",
    "reproducible-experiment": "сделай воспроизводимость: seed, окружение, provenance, манифест",
    "causal-claim-audit": "проверь, влияет ли X на Y или это confound, причинность",
    "api-compat-contract": "проверь совместимость api: contract tests, breaking change и semver для sdk",
    "test-coverage-synthesis": "напиши тесты для модуля: покрытие, property-based hypothesis, граничные условия",
    "paper-falsification-audit": "проверь, воспроизводятся ли графики из статьи на arXiv",
    "experiment-protocol": "составь протокол эксперимента, нужна контрольная группа и размер выборки",
    "algorithmic-complexity": "снизь асимптотическую сложность алгоритма на графе, нужна кривая масштабирования",
    "reproducible-build": "сделай воспроизводимую сборку: reproducible build, хэш артефакта, чистое окружение",
    "dependency-modernization": "обнови зависимости: lockfile, устаревшие пакеты, pip-audit",
    "invariants-verification": "проверь критические инварианты: property-based, mutation testing, контрпримеры",
    "systematic-review": "сделай систематический обзор литературы по теме, найди публикации",
}


def routed_for(card: str) -> dict:
    r = lib.route(CANON[card], index)
    assert r["card"] is not None and r["card"]["id"] == card, (card, r["card"])
    return r


def block(arm: str, task: str, statement: str) -> str:
    good, wrong = TASKS[task]
    if arm == "C":
        return ""
    if arm == "H":
        return "Подсказка системы:\n" + lib.hint(routed_for(good)) + "\n\n"
    card = good if arm == "F" else wrong
    r = routed_for(card)
    return (
        "Контракт задачи (так его показывает команда /contract):\n"
        + lib.draft(r, index, statement)
        + "\n\n"
    )


TEMPLATE = (
    "Ты помогаешь пользователю с его задачей. Работай только внутри папки {dir}. Не открывай другие папки и файлы "
    "вне неё. Не запускай других агентов, всё делай сам. Не больше 40 вызовов инструментов.\n\n"
    "{block}"
    "Задача пользователя: {statement}\n\n"
    "Итог запиши в {dir}/report.md: что именно нашёл, чем подтверждено (команды, числа, строки файлов) и что "
    "предлагаешь сделать. Пиши по существу."
)

plan = []
rnd = random.Random(20261014)
ids = set()


def newid() -> str:
    while True:
        x = "x" + "".join(rnd.choice("0123456789abcdef") for _ in range(4))
        if x not in ids:
            ids.add(x)
            return x


for task in TASKS:
    statement = (HERE / "statements" / f"{task}.txt").read_text(encoding="utf-8").strip()
    for arm, rep in (("C", 1), ("C", 2), ("F", 1), ("F", 2), ("H", 1), ("W", 1)):
        rid = newid()
        rdir = HERE / "runs" / rid
        shutil.copytree(HERE / "tasks" / task / "material", rdir)
        prompt = TEMPLATE.format(
            dir=str(rdir).replace("\\", "/"), block=block(arm, task, statement), statement=statement
        )
        (HERE / "prompts").mkdir(exist_ok=True)
        (HERE / "prompts" / f"{rid}.txt").write_text(prompt, encoding="utf-8")
        plan.append({"run": rid, "task": task, "arm": arm, "rep": rep, "chars": len(prompt)})
rnd.shuffle(plan)
json.dump(plan, open(HERE / "plan_SECRET.json", "w"), indent=1)
print("runs", len(plan))
print(
    "prompt chars by arm:",
    {
        a: sorted(p["chars"] for p in plan if p["arm"] == a)[
            len([1 for p in plan if p["arm"] == a]) // 2
        ]
        for a in "CFHW"
    },
)
